import base64
from pathlib import Path

ASSETS = {
    "icon.png": "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR4nGNgYAAAAAMAASsJTYQAAAAASUVORK5CYII=",
    "splash.png": "",
    "adaptive-icon.png": "iVBORw0KGgoAAAANSUhEUgAAAA8AAAAQCAYAAADJViUEAAAACXBIWXMAAAsTAAALEwEAmpwYAAAAVElEQVQoz2NgwAKGQYGB4T8gYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBgYGBjAAAN0gXk6w2mGQAAAABJRU5ErkJggg==",
    "favicon.png": "iVBORw0KGgoAAAANSUhEUgAAAA4AAAAOCAYAAAAfSC3RAAAACXBIWXMAAAsTAAALEwEAmpwYAAAAPElEQVQoz2NgQAP/Gf4z8DAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMAAEA+gT9cN2hGwAAAABJRU5ErkJggg=="
}

ROOT = Path(__file__).resolve().parents[1]
ASSETS_DIR = ROOT / "assets"
ASSETS_DIR.mkdir(parents=True, exist_ok=True)

for name, b64 in ASSETS.items():
    path = ASSETS_DIR / name
    with open(path, "wb") as f:
        f.write(base64.b64decode(b64))
    print(f"Wrote {path}")
